int git_index_read_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const git_index_entry *entry = buffer;
    git_index_entry *new_entry;
    size_t path_len, name_len;
    int is_offset;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    if (entry->flags & GIT_INDEXENTRY_JUST_ADDED) {
        return -1;
    }

    name_len = strlen(entry->path);
    path_len = (name_len + last ? strlen(last) + 1 : 0);

    new_entry = (git_index_entry *)malloc(sizeof(git_index_entry) + path_len);
    if (!new_entry) {
        return -1;
    }

    memcpy(new_entry, entry, sizeof(git_index_entry));
    new_entry->path = (char *)new_entry + sizeof(git_index_entry);

    if (last) {
        snprintf(new_entry->path, path_len, "%s/%s", last, entry->path);
    } else {
        strcpy(new_entry->path, entry->path);
    }

    *out = new_entry;
    *out_size = sizeof(git_index_entry) + path_len;

    return 0;
}

