int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const char *buf = buffer;
    git_index_entry *entry;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    size_t entry_size = sizeof(git_index_entry);
    if (entry->flags_extended & GIT_INDEX_ENTRY_CASE) {
        entry_size += strlen(last) + 1;
        entry->path = (char *)malloc(entry_size);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        snprintf(entry->path, entry_size, "%s%s", last, entry->path);
    } else {
        entry->path = (char *)malloc(entry_size);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        memcpy(entry->path, buf + sizeof(git_index_entry), entry_size - sizeof(git_index_entry));
    }

    *out = entry;
    *out_size = entry_size;
    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const char *buffer_ptr = buffer;
    const git_index_entry *entry = (const git_index_entry *)buffer_ptr;
    size_t entry_size = sizeof(git_index_entry);
    size_t path_len = strlen(entry->path);

    if (buffer_size < entry_size) {
        return -1;
    }

    *out = malloc(entry_size);
    if (!*out) {
        return -1;
    }

    memcpy(*out, entry, entry_size);

    if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
        char *full_path = malloc(path_len + strlen(last) + 2);
        if (!full_path) {
            free(*out);
            *out = NULL;
            return -1;
        }

        snprintf(full_path, path_len + strlen(last) + 2, "%s/%s", last, entry->path);
        strncpy((*out)->path, full_path, strlen(full_path) + 1);
        free(full_path);
    } else {
        strncpy((*out)->path, entry->path, path_len + 1);
    }

    *out_size = entry_size;

    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const uint8_t *buf = (const uint8_t *)buffer;
    git_index_entry *entry;
    size_t entry_size;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    if (entry->flags_extended & GIT_INDEX_ENTRY_COMpressed) {
        size_t path_len = strlen((const char *)buf + sizeof(git_index_entry));
        if (buffer_size < sizeof(git_index_entry) + path_len) {
            free(entry);
            return -1;
        }
        entry->path = (char *)malloc(path_len + 1);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        snprintf(entry->path, path_len + 1, "%s", (const char *)buf + sizeof(git_index_entry));
    } else {
        if (last) {
            size_t path_len = strlen((const char *)buf + sizeof(git_index_entry)) + strlen(last) + 1;
            if (buffer_size < sizeof(git_index_entry) + path_len) {
                free(entry);
                return -1;
            }
            entry->path = (char *)malloc(path_len);
            if (!entry->path) {
                free(entry);
                return -1;
            }
            snprintf(entry->path, path_len, "%s%s", last, (const char *)buf + sizeof(git_index_entry));
        } else {
            entry->path = strdup((const char *)buf + sizeof(git_index_entry));
            if (!entry->path) {
                free(entry);
                return -1;
            }
        }
    }

    *out = entry;
    *out_size = sizeof(git_index_entry) + strlen(entry->path) + 1;
    return 0;
